import { isEmpty, omitEmpty } from '@splendidlabz/utils'
import { resizeObserver } from '@splendidlabz/utils/dom'

const DEFAULT_BREAKPOINT_OPTIONS = {
  breakpoints: {},
  breakpointType: 'media', // media
  callback: null,
}

export function breakpointObserver(node, props = {}) {
  const options = { ...DEFAULT_BREAKPOINT_OPTIONS, ...omitEmpty(props) }
  if (isEmpty(options.breakpoints)) return

  const { breakpointType } = options

  let observedNode
  if (breakpointType === 'media') observedNode = document.body
  else observedNode = node

  let activeBreakpointValue = 0
  const breakpoints = createBreakpointArray(options.breakpoints)

  const observer = resizeObserver(observedNode, {
    observe: true,
    callback: observerCB,
  })

  // Observer Callback
  function observerCB({ entry }) {
    let { width } = entry.contentRect
    if (breakpointType === 'media') width = window.innerWidth

    // Check for the current breakpoint
    const currentBreakpoint = getCurrentBreakpoint({ breakpoints, width })
    const { breakpoint, value } = currentBreakpoint

    // Check if breakpoint is active
    if (activeBreakpointValue === breakpoint) return
    activeBreakpointValue = breakpoint

    // Runs callback
    if (options.callback)
      options.callback({
        node: observedNode,
        breakpoint,
        value,
        observer,
      })
  }

  return {
    destroy() {
      observer.disconnect(observedNode)
    },
  }
}

// breakpoints={{
//   0: { ... },
//   1000: { ... },
// }}
function createBreakpointArray(breakpoints) {
  return Object.entries(breakpoints).map(([key, value]) => {
    return { breakpoint: parseFloat(key), value }
  })
}

function getCurrentBreakpoint({ breakpoints, width }) {
  const filtered = breakpoints.filter(({ breakpoint }) => width >= breakpoint)
  return filtered[filtered.length - 1]
}
